            )}
          </AutocompleteList>

          {getOptionsInfiniteQuery.isFetchingNextPage && (
            <AutocompleteStatus className='flex justify-center'>
              <Spinner />
            </AutocompleteStatus>
          )}
        </AutocompleteContent>
      </Autocomplete>
    </SmartFormFieldContainer>
  )
}

